 @SuppressWarnings("unchecked") private Map<String,Object> canonical(Map<String,Object>raw){Map<String,Object>r=new LinkedHashMap<>();for(String k:Arrays.asList("return_sn","external_order","owner_code","warehouse_code","message_id","status","outbound_time","carrier_code","carrier_name","waybill"))r.put(k,text(raw.get(k)));r.put("complete",Boolean.TRUE.equals(raw.get("complete")));r.put("snapshot_version",text(raw.get("snapshot_version")).isEmpty()?0:id(raw.get("snapshot_version")));Map<Long,Map<String,Object>>lines=new TreeMap<>();for(Map<String,Object>l:(List<Map<String,Object>>)raw.get("lines")){long key=n(l,"line_key"),q=n(l,"quantity");require(q>=0&&q<=100000000,"回传数量无效");Map<String,Object>copy=map("line_key",key,"quantity",q,"sku_sn",text(l.get("sku_sn")),"batch_code",text(l.get("batch_code")),"inventory_type",text(l.get("inventory_type")),"owner_code",text(l.get("owner_code")));if(lines.containsKey(key)){Map<String,Object>old=lines.get(key);for(String k:Arrays.asList("sku_sn","batch_code","inventory_type","owner_code"))require(old.get(k).equals(copy.get(k)),"原行批次质量与来源不一致");old.put("quantity",Math.addExact(n(old,"quantity"),q));}else lines.put(key,copy);}require(lines.size()<=200,"原行数量超过上限");r.put("lines",new ArrayList<>(lines.values()));r.put("total_lines",raw.get("total_lines")==null?lines.size():id(raw.get("total_lines")));List<Map<String,Object>>packs=raw.get("packages") instanceof List?(List<Map<String,Object>>)raw.get("packages"):Collections.emptyList();require(packs.size()<=100,"单消息包裹数超过上限");r.put("packages",packs);return r;}
